-- ============================================
-- Tambahan: Eliminasi Urin/Fekal (D.0040-D.0051)
-- ============================================



DELETE FROM sdki_slki_relations
WHERE luaran_id = 0
AND diagnosa_id IN (
  SELECT id FROM diagnosa_sdki
  WHERE kode_diagnosa IN ('D.0040','D.0041','D.0042','D.0043','D.0044','D.0045','D.0046','D.0047','D.0048','D.0050','D.0051')
);




