INSERT IGNORE INTO intervensi_siki (kode_intervensi, label_intervensi, kategori, subkategori, definisi) VALUES
('I.01001', 'Latihan Batuk Efektif', 'Fisiologis', 'Respirasi', 'Melatih pasien yang tidak memiliki kemampuan batuk secara efektif untuk membersihkan laring, trakea dan bronkiolus dari sekret atau benda asing di jalan napas.'),
('I.01011', 'Manajemen Jalan Napas', 'Fisiologis', 'Respirasi', 'Mengidentifikasi dan mengelola kepatenan jalan napas.'),
('I.01014', 'Pemantauan Respirasi', 'Fisiologis', 'Respirasi', 'Mengumpulkan dan menganalisis data untuk memastikan kepatenan jalan napas dan keefektifan pertukaran gas.'),
('I.01021', 'Penyapihan Ventilasi Mekanik', 'Fisiologis', 'Respirasi', 'Memfasilitasi pasien bernapas tanpa bantuan ventilasi mekanis.'),
('I.01026', 'Terapi Oksigen', 'Fisiologis', 'Respirasi', 'Memberikan tambahan oksigen untuk mencegah dan mengatasi kondisi kekurangan oksigen jaringan.'),
('I.01018', 'Pencegahan Aspirasi', 'Fisiologis', 'Respirasi', 'Mengidentifikasi dan mengurangi risiko masuknya partikel makanan/cairan ke dalam paru-paru.'),
('I.02038', 'Manajemen Defibrilasi', 'Fisiologis', 'Sirkulasi', 'Mengidentifikasi dan mengelola aliran listrik kuat dengan metode asinkron ke jantung melalui elektroda yang ditempatkan pada permukaan dada.'),
('I.03139', 'Resusitasi Cairan', 'Fisiologis', 'Sirkulasi', 'Mengidentifikasi dan mengelola pemberian cairan secara cepat untuk mengatasi kehilangan cairan.'),
('I.02083', 'Resusitasi Jantung Paru', 'Fisiologis', 'Sirkulasi', 'Memberikan pertolongan pertama pada kondisi henti napas dan henti jantung dengan teknik kombinasi kompresi pada dada dan bantuan napas.'),
('I.02075', 'Perawatan Jantung', 'Fisiologis', 'Sirkulasi', 'Mengidentifikasi, merawat dan membatasi komplikasi akibat ketidakseimbangan antara suplai dan konsumsi oksigen miokard.'),
('I.02076', 'Perawatan Sirkulasi', 'Fisiologis', 'Sirkulasi', 'Mengidentifikasi dan merawat area lokal dengan keterbatasan sirkulasi perifer.'),
('I.06195', 'Manajemen Sensasi Perifer', 'Fisiologis', 'Neurosensori', 'Mengidentifikasi dan mengelola ketidaknyamanan atau perubahan sensasi pada area perifer.'),
('I.02080', 'Pertolongan Pertama', 'Fisiologis', 'Sirkulasi', 'Memberikan penanganan dasar dan segera pada kondisi kegawatdaruratan baik dengan alat maupun tanpa alat.'),
('I.02067', 'Pencegahan Perdarahan', 'Fisiologis', 'Sirkulasi', 'Mengidentifikasi dan menurunkan risiko atau komplikasi stimulus yang menyebabkan perdarahan atau risiko perdarahan.'),
('I.02028', 'Balut Tekan', 'Fisiologis', 'Sirkulasi', 'Membalut luka dengan tekanan untuk mencegah atau menghentikan perdarahan.'),
('I.12378', 'Edukasi Keamanan Anak', 'Perilaku', 'Penyuluhan dan Pembelajaran', 'Memberikan informasi mengenai keamanan dan pencegahan cidera pada anak.'),
('I.12379', 'Edukasi Keamanan Bayi', 'Perilaku', 'Penyuluhan dan Pembelajaran', 'Menyediakan informasi dan dukungan terhadap pencegahan cedera pada bayi.'),
('I.01004', 'Manajemen Perdarahan', 'Fisiologis', 'Respirasi', 'Mengidentifikasi dan mengelola kehilangan darah saat terjadi perdarahan.'),
('I.03094', 'Konseling Nutrisi', 'Fisiologis', 'Nutrisi dan Cairan', 'Memberikan bimbingan dalam melakukan modifikasi asupan nutrisi.'),
('I.06194', 'Manajemen Peningkatan Tekanan Intrakranial', 'Fisiologis', 'Neurosensori', 'Mengidentifikasi dan mengelola peningkatan tekanan dalam rongga kranial.'),
('I.02068', 'Pencegahan Syok', 'Fisiologis', 'Sirkulasi', 'Mengidentifikasi dan menurunkan risiko terjadinya ketidakmampuan tubuh menyediakan oksigen dan nutrien untuk mencukupi kebutuhan jaringan.'),
('I.03119', 'Manajemen Berat Badan', 'Fisiologis', 'Nutrisi dan Cairan', 'Mengelola perubahan berat badan untuk mencapai berat badan yang optimal.'),
('I.05178', 'Manajemen Perilaku', 'Perilaku', 'Penyuluhan dan Pembelajaran', 'Mengidentifikasi dan mengelola perilaku negatif yang dapat mengganggu kesehatan.'),
('I.05183', 'Promosi Latihan Fisik', 'Perilaku', 'Penyuluhan dan Pembelajaran', 'Memfasilitasi aktivitas fisik secara rutin untuk mempertahankan atau meningkatkan derajat kebugaran dan kesehatan.'),
('I.03119b', 'Manajemen Nutrisi', 'Fisiologis', 'Nutrisi dan Cairan', 'Mengidentifikasi dan mengelola asupan nutrisi yang seimbang.'),
('I.03101', 'Manajemen Diare', 'Fisiologis', 'Nutrisi dan Cairan', 'Mengidentifikasi dan mengelola diare dan dampaknya.');
